#include<stdio.h>
int	main()
{
	int	a[144];
	int	n = 144;
	for (int i = 0; i < n; i++) {
		if (i % 5 == 1 || i % 5 == 2) a[i] = 1;
		else if (i % 5 == 4) a[i] = 2;
		else a[i] = 3;
	}
	int	b = a[0], m = 1;
	for (int i = 1; i < n; i++) {
		if (m == 0) {
			b = a[i];
			m = 1;
		}
		else {
			if (b % 2 == 0) {
				b += a[i];
				m--;
			}
			else {
				b -= a[i];
			}
		}
	}
	printf("%d", b);
	return	0;
}

