#include<stdio.h>

int main()
{
    int a[3], b[3], c[3];
    int d = 0;
    for(int i=0 ; i<3 ; i++) {
        a[i] = i + 2;
        b[i] = i * 4;
        c[i] = i * i;
    }
    for(int i=0 ; i<3 ; i++) {
        for(int j=0 ; j<3 ; j++) {
            for(int k=0 ; k<3 ; k++) {
                d += a[i] + b[j] * c[k];
            }
        }
    }

    printf("%d", d);
    return 0;
}

